#pragma once

// The CPU test's golden tables (Phase 2 design §6.4). Each golden/<name>.inc
// is generated by tools/cpu-golden (the synbench-cpu-golden tool, the scalar
// reference build) and committed with a header saying how it was made. They
// are platform-independent: one table, checked on every OS and architecture,
// which is why the kernels are bit-exact (§6.2). A table that changes means a
// CPU testVersion bump. The CTest cpu_golden_tables regenerates every table on
// each CI platform and fails if one differs from the committed file.

#include <array>
#include <cstdint>

namespace sb::cpu::golden {

#include "tests/cpu/golden/corpus.inc"
#include "tests/cpu/golden/int.inc"
#include "tests/cpu/golden/fp.inc"
#include "tests/cpu/golden/primes.inc"
#include "tests/cpu/golden/simd.inc"
#include "tests/cpu/golden/compress.inc"

} // namespace sb::cpu::golden
